<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasOne;
class VoiceAudioClip extends Model { use HasUuid; protected $fillable=['voice_recording_id','voice_report_id','discord_guild_id','discord_channel_id','reported_user_discord_id','storage_path','mime_type','size_bytes','duration_seconds','captured_from','captured_until','status','error_message']; protected function casts(): array{return ['size_bytes'=>'integer','duration_seconds'=>'integer','captured_from'=>'datetime','captured_until'=>'datetime'];} protected static function booted(): void {static::deleting(function(VoiceAudioClip $clip): void {$path=$clip->resolvedStoragePath(); if($path&&is_file($path))@unlink($path);}); static::deleted(function(VoiceAudioClip $clip): void {$clip->recording?->refreshSummary();});} public function recording(): BelongsTo{return $this->belongsTo(VoiceRecording::class,'voice_recording_id');} public function report(): BelongsTo{return $this->belongsTo(VoiceReport::class,'voice_report_id');} public function guild(): BelongsTo{return $this->belongsTo(DiscordGuild::class,'discord_guild_id');} public function channel(): BelongsTo{return $this->belongsTo(DiscordChannel::class,'discord_channel_id');} public function transcript(): HasOne{return $this->hasOne(VoiceTranscript::class,'voice_audio_clip_id');} public function resolvedStoragePath(): ?string { $path=$this->storage_path; $candidates=str_starts_with($path,'/')?[$path]:[base_path($path),base_path('../discord-manager/'.$path),dirname(base_path(),2).'/'.$path]; foreach($candidates as $candidate){if(is_file($candidate))return $candidate;} return null; } public function displayName(): string {return DiscordMember::query()->where('discord_guild_id',$this->discord_guild_id)->where('discord_id',$this->reported_user_discord_id)->value('display_name') ?: $this->reported_user_discord_id;} public function humanSize(): string {return number_format($this->size_bytes/1024/1024,2,',',' ').' Mo';} }
